(()=>{let t=window.pageYOffset;document.addEventListener("wheel",e=>{const n=window.pageYOffset,i=e.deltaY>0?t<document.body.scrollHeight-window.innerHeight:t>0;if(i){e.preventDefault();t+=e.deltaY;t=Math.min(Math.max(t,0),document.body.scrollHeight-window.innerHeight)}}),function s(){const e=window.pageYOffset,n=t-e;if(Math.abs(n)>0.5)window.scrollTo(0,e+n*.1);requestAnimationFrame(s)}()})();
